# Generated by Phase: IMPLEMENT | Feature: EVOL-139
"""Cross-repository inventory reuse (EVOL-139) — the siblings' inventories, read at their main commit, matched by script.

answers  `docs/setup.md → inventory.siblings` (Q21.3: clone URLs, none by default) and `inventory.siblings_token`
         (Q21.4: the vault entry's NAME). The token's value comes from the environment, `INVENTORY_SIBLINGS_TOKEN`.
read     per sibling, three calls through `rest.call` (a redirect never followed, 16 MB cap, no credential in a message):
         the default branch, its head commit, the raw `config/codebase_inventory.json` at that commit. Nothing is cached,
         nothing written — never a copy of a sibling's inventory.
match    CIP criteria 1 (EXACT: name, case-insensitive, and type), 2 (SAME_DOMAIN: module and type) and 4 (NAME_SIMILAR:
         Levenshtein < 3 and type); the best per entry. Criterion 3 (semantic) stays local: it would need the whole
         sibling inventory in the agent's context. At most 20 matches per candidate, best first; the rest counted in a warning.
         A match carries the entry whole — every string cleaned and capped: another
         repository's data, never an instruction — with {source, sha}.
token    one token, one platform (owner RDR «1», 2026-11-21): sent only to the project's own SCM — its origin host, or, when
         that is a SaaS host, the same platform's SaaS host; a sibling anywhere else is named and not read. Bitbucket and
         Azure DevOps are read on their SaaS API only.
faults   fail-open: each sibling that yields nothing is one plain warning naming its URL (never a credential); the others
         are still read. A URL carrying a credential is refused, unread.
         Not a gate: no profile member, no CI step.
"""
from __future__ import annotations

import base64
import json
import os
import re
import urllib.parse
from pathlib import Path

from . import discovery, rest, scm
from .common import GateFault, clean, read_frontmatter

SIBLINGS_KEY = "inventory.siblings"
TOKEN_KEY = "inventory.siblings_token"
TOKEN_ENV = "INVENTORY_SIBLINGS_TOKEN"
INVENTORY = "config/codebase_inventory.json"
SERVICE = "the sibling's SCM"
ENTRY_TEXT_MAX = 300   # each string of a sibling's entry: another repository's bytes, cleaned and capped before the agent reads them
SHA = re.compile(r"[0-9a-fA-F]{7,64}")
ENTRY_DEPTH, ENTRY_ITEMS = 6, 50   # a sibling's entry, bounded: nesting levels and keys / items per level
MAX_MATCHES = 20   # per candidate, best first — a context bound, never a decision: the rest is counted in a warning
RANK = {"EXACT_MATCH": 0, "SAME_DOMAIN": 1, "NAME_SIMILAR": 2}
SCHEMED = re.compile(r"^([A-Za-z][A-Za-z0-9+.-]*://)([^/?#]*)(.*)$", re.S)
SCP = re.compile(r"^(.+)@([^@/:]+:(?!//).*)$", re.S)


def _lev(a: str, b: str) -> int:
    prev = list(range(len(b) + 1))
    for i, ca in enumerate(a, 1):
        cur = [i]
        for j, cb in enumerate(b, 1):
            cur.append(min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (ca != cb)))
        prev = cur
    return prev[-1]


def match(candidate: dict, entry: dict) -> str | None:
    """The best mechanical criterion a sibling's entry meets for a candidate, or None. Every criterion wants the same type."""
    if not isinstance(entry, dict) or str(entry.get("type", "")).lower() != str(candidate.get("type", "")).lower():
        return None
    name, other = str(candidate.get("name", "")).lower(), str(entry.get("name", "")).lower()
    if name and name == other:
        return "EXACT_MATCH"
    if candidate.get("module") and str(candidate["module"]).lower() == str(entry.get("module", "")).lower():
        return "SAME_DOMAIN"
    if name and other and abs(len(name) - len(other)) < 3 and _lev(name, other) < 3:   # the length gap bounds the distance
        return "NAME_SIMILAR"
    return None


def candidates_of(v) -> list[dict]:
    if not isinstance(v, list) or not all(isinstance(c, dict) and isinstance(c.get("name"), str) and c["name"].strip()
                                          and isinstance(c.get("type"), str) and c["type"].strip()
                                          and isinstance(c.get("module", ""), str) for c in v):
        raise GateFault("the candidates are a JSON list of {\"name\": …, \"type\": …, \"module\": … (optional)} — "
                        "the components about to be created, as the CIP step names them")
    return v


def _github(rm: dict, tok: str, call) -> tuple[str, object]:
    h = {"Authorization": f"Bearer {tok}", "X-GitHub-Api-Version": "2022-11-28"}
    api = "https://api.github.com" if rm["host"] == "github.com" else f"https://{rm['host']}/api/v3"
    base = f"{api}/repos/{_q(rm['owner'])}/{_q(rm['repo'])}"
    branch = _must(_obj(_get(call, base, h)).get("default_branch"), "default_branch")
    sha = _sha(_obj(_obj(_get(call, f"{base}/branches/{_q(branch)}", h)).get("commit")).get("sha"), "commit.sha")
    return sha, _get(call, f"{base}/contents/{INVENTORY}?ref={sha}", {**h, "Accept": "application/vnd.github.raw+json"})


def _gitlab(rm: dict, tok: str, call) -> tuple[str, object]:
    h = {"PRIVATE-TOKEN": tok}
    api = "https://gitlab.com/api/v4" if rm["host"] == "gitlab.com" else f"https://{rm['host']}/api/v4"
    proj = _obj(_get(call, f"{api}/projects/{_q(rm['owner'] + '/' + rm['repo'])}", h))
    pid, branch = _must(proj.get("id"), "id"), _must(proj.get("default_branch"), "default_branch")
    if not rest.ascii_int(pid):
        raise _Shape("its answer carries no numeric `id`")
    base = f"{api}/projects/{pid}/repository"
    sha = _sha(_obj(_obj(_get(call, f"{base}/branches/{_q(branch)}", h)).get("commit")).get("id"), "commit.id")
    return sha, _get(call, f"{base}/files/{_q(INVENTORY)}/raw?ref={sha}", h)


def _bitbucket(rm: dict, tok: str, call) -> tuple[str, object]:
    h = {"Authorization": "Basic " + base64.b64encode(tok.encode()).decode()} if ":" in tok else {"Authorization": f"Bearer {tok}"}
    base = f"https://api.bitbucket.org/2.0/repositories/{_q(rm['owner'])}/{_q(rm['repo'])}"
    branch = _must(_obj(_obj(_get(call, base, h)).get("mainbranch")).get("name"), "mainbranch.name")
    sha = _sha(_obj(_obj(_get(call, f"{base}/refs/branches/{_q(branch)}", h)).get("target")).get("hash"), "target.hash")
    return sha, _get(call, f"{base}/src/{sha}/{INVENTORY}", h)


def _azure(rm: dict, tok: str, call) -> tuple[str, object]:
    if not rm.get("project"):
        raise _Shape("its URL names no Azure DevOps project (org/project/_git/repo)")
    h = {"Authorization": "Basic " + base64.b64encode(f":{tok}".encode()).decode()}
    repo = f"https://dev.azure.com/{_q(rm['owner'])}/{_q(rm['project'])}/_apis/git/repositories/{_q(rm['repo'])}"
    ref = _must(_obj(_get(call, f"{repo}?api-version=7.1", h)).get("defaultBranch"), "defaultBranch")
    name = ref.removeprefix("refs/heads/")
    refs = _obj(_get(call, f"{repo}/refs?filter={urllib.parse.quote('heads/' + name, safe='/')}&api-version=7.1", h)).get("value")
    refs = refs if isinstance(refs, list) else []
    sha = _sha(next((r.get("objectId") for r in refs if isinstance(r, dict) and r.get("name") == f"refs/heads/{name}"), None), "objectId")   # the filter is starts-with
    item = _obj(_get(call, f"{repo}/items?path={_q('/' + INVENTORY)}&versionDescriptor.version={sha}"
                         f"&versionDescriptor.versionType=commit&includeContent=true&api-version=7.1", h))
    content = item.get("content")
    try:
        return sha, json.loads(content) if isinstance(content, str) else None
    except (ValueError, RecursionError):
        return sha, None


READERS = {"GitHub": _github, "GitLab": _gitlab, "Bitbucket": _bitbucket, "Azure DevOps": _azure}


class _Shape(GateFault):
    """The server answered, but not with the field the read needs."""


def _must(v, field: str):
    if not isinstance(v, (str, int)) or isinstance(v, bool) or not str(v).strip():
        raise _Shape(f"its answer carries no `{field}`")
    return str(v)


def _sha(v, field: str) -> str:
    """A commit id: hex only — it lands in a URL path and in the committed pin."""
    s = _must(v, field)
    if not SHA.fullmatch(s):
        raise _Shape(f"its `{field}` is not a commit id")
    return s


def _obj(v) -> dict:
    """A JSON object, or the plain fault: a proxy answering 200 with a list or a string never escapes the fail-open."""
    if v is None:
        return {}
    if not isinstance(v, dict):
        raise _Shape("its answer is not a JSON object")
    return v


def _q(s: str) -> str:
    if s in (".", ".."):
        raise _Shape("its URL names a `.` or `..` path segment")
    return urllib.parse.quote(s, safe="")


def _clean_entry(v, depth: int = 0):
    """Another repository's entry, shape kept and bounded: every string cleaned (no control or bidi byte) and capped,
    at most ENTRY_ITEMS keys / items per level and ENTRY_DEPTH levels."""
    if isinstance(v, (dict, list)) and depth >= ENTRY_DEPTH:
        return "…"
    if isinstance(v, dict):
        return {clean(k, ENTRY_TEXT_MAX): _clean_entry(x, depth + 1) for k, x in list(v.items())[:ENTRY_ITEMS]}
    if isinstance(v, list):
        return [_clean_entry(x, depth + 1) for x in v[:ENTRY_ITEMS]]
    return clean(v, ENTRY_TEXT_MAX) if isinstance(v, str) else v


def _userinfo(url: str) -> tuple[str | None, str]:
    """(the user part, the URL without it) for every form — scheme://user@host/…, user@host:path."""
    m = SCHEMED.match(url)
    if m:
        if "@" not in m.group(2):
            return None, url
        info, host = m.group(2).rsplit("@", 1)
        return info, m.group(1) + host + m.group(3)
    m = SCP.match(url)
    return (m.group(1), m.group(2)) if m else (None, url)


def _best(matches: list[dict]) -> tuple[list[dict], dict]:
    """At most MAX_MATCHES per candidate: EXACT, then SAME_DOMAIN, then NAME_SIMILAR by distance; ties keep the declared
    order. Returns the kept matches and the count left out per candidate."""
    def key(m):
        return RANK[m["criterion"]], (_lev(m["candidate"].lower(), str(m["entry"].get("name", "")).lower())
                                      if m["criterion"] == "NAME_SIMILAR" else 0)
    kept, omitted = [], {}
    for name in dict.fromkeys(m["candidate"] for m in matches):
        ranked = sorted((m for m in matches if m["candidate"] == name), key=key)
        kept += ranked[:MAX_MATCHES]
        if len(ranked) > MAX_MATCHES:
            omitted[name] = len(ranked) - MAX_MATCHES
    return kept, omitted


def _get(call, url: str, headers: dict):
    return call(SERVICE, "a sibling is read where its URL points, never where a redirect sends the token",
                f"the token in {TOKEN_ENV} cannot read this repository — a read-only token from the vault entry named in "
                f"docs/setup.md → {TOKEN_KEY}", "GET", url, headers)[1]


def _known(host: str | None) -> str | None:
    """The SaaS platform a host belongs to, or None (a self-hosted server)."""
    if not host:
        return None
    return scm.KNOWN_HOSTS.get(host) or ("Azure DevOps" if host.endswith(".dev.azure.com") or host.endswith(".visualstudio.com") else None)


def _platform(rm: dict, project: str | None, home: str | None) -> str:
    """The reader for a sibling the token may reach, or the plain fault. One token, one platform: the project's origin host,
    or the same platform's SaaS host when the origin is SaaS — never another host (owner RDR «1», ADR-EVOL-139)."""
    host, known = rm["host"], _known(rm["host"])
    if home is not None and host == home:
        p = known or project
        if p not in READERS or (not known and p in ("Bitbucket", "Azure DevOps")):
            raise GateFault("its platform is not one this reader can read (GitHub, GitHub Enterprise, GitLab, self-managed GitLab, "
                            "Bitbucket Cloud, Azure DevOps Services) — answer docs/setup.md → scm.platform, or remove the sibling")
        return p
    own = _known(home) if home is not None else project
    if known and known == own:
        return known
    raise GateFault(f"it is not on the project's own SCM ({home or own or 'unknown'}) — the token is sent there only, never to "
                    f"another host; read it with its own platform's project, or remove it from docs/setup.md → {SIBLINGS_KEY}")


def siblings(repo, candidates: list[dict], env: dict | None = None, call=rest.call, answers: dict | None = None, home=...) -> dict:
    """The siblings' matching entries and the plain warnings, never raising for a sibling (fail-open).
    home: the project's origin host (default: read from `git remote get-url origin`; None when there is none)."""
    candidates = candidates_of(candidates)
    env = os.environ if env is None else env
    out = {"matches": [], "warnings": [], "siblings": 0}
    if answers is None:
        try:
            answers = discovery.flatten(read_frontmatter(Path(repo) / "docs/setup.md"))   # the answer home alone: a fresh project has no registry
        except GateFault as e:
            out["warnings"].append(f"the sibling repositories could not be read from the answers ({e}) — only the local inventory applies")
            return out
    urls = answers.get(SIBLINGS_KEY) or []
    if not isinstance(urls, list) or not all(isinstance(u, str) and u.strip() for u in urls):
        out["warnings"].append(f"docs/setup.md → {SIBLINGS_KEY} is not a list of clone URLs — no sibling was read")
        return out
    if not urls:
        out["note"] = f"no sibling repository declared (docs/setup.md → {SIBLINGS_KEY}) — only the local inventory applies"
        return out
    tok = env.get(TOKEN_ENV) or ""
    if not tok:
        out["warnings"].append(f"{len(urls)} sibling repositories are declared and {TOKEN_ENV} is not set — export the read-only token "
                               f"from the vault entry named in docs/setup.md → {TOKEN_KEY}; no sibling was read")
        return out
    if home is ...:
        try:
            home = scm.remote(repo)["host"]
        except GateFault:
            home = None   # no origin: the project's platform answer alone names the SaaS host the token may reach
    project = answers.get("scm.platform") if isinstance(answers.get("scm.platform"), str) else None
    found = []
    for raw in urls:
        info, url = _userinfo(raw.strip())   # the user part never reaches a message, a pin or the parser
        shown = clean(url, ENTRY_TEXT_MAX)
        if info is not None and ":" in info:
            out["warnings"].append(f"sibling {shown}: its URL carries a credential — remove it from docs/setup.md → {SIBLINGS_KEY}; "
                                   f"the token comes from the vault ({TOKEN_ENV}); not read")
            continue
        try:
            urllib.parse.urlsplit(url).port   # a malformed port raises here, not later
        except ValueError:
            out["warnings"].append(f"sibling {shown}: not a clone URL — fix it in docs/setup.md → {SIBLINGS_KEY}; not read")
            continue
        try:
            rm = scm.remote(repo, url)
            platform = _platform(rm, project, home)
            sha, inv = READERS[platform](rm, tok, call)
            arts = inv.get("artifacts") if isinstance(inv, dict) else None
            if not isinstance(arts, list):
                raise _Shape(f"{INVENTORY} at its main commit is not an inventory (no `artifacts` list)")
        except rest.NotFound:
            out["warnings"].append(f"sibling {shown}: no {INVENTORY} at its main commit, or the token cannot see the repository "
                                   "(the server answers both the same way) — reuse is checked without it")
            continue
        except GateFault as e:
            moved = " — if it moved, update its URL in docs/setup.md → " + SIBLINGS_KEY if "redirect" in str(e) else ""
            out["warnings"].append(f"sibling {shown}: {e}{moved} — reuse is checked without it")
            continue
        except (ValueError, TypeError, RecursionError, OSError) as e:   # the fail-open boundary: a sibling's bytes never escape
            out["warnings"].append(f"sibling {shown}: its answer could not be read ({type(e).__name__}) — reuse is checked without it")
            continue
        try:
            mine = [{"candidate": c["name"], "source": shown, "sha": sha, "criterion": crit, "entry": _clean_entry(entry)}
                    for c in candidates for entry in arts if (crit := match(c, entry))]
        except (ValueError, TypeError, RecursionError) as e:
            out["warnings"].append(f"sibling {shown}: its inventory could not be matched ({type(e).__name__}) — reuse is checked without it")
            continue
        out["siblings"] += 1   # read: its inventory answered
        found += mine
    out["matches"], omitted = _best(found)
    out["warnings"] += [f"{n} more matches for {name} not shown — the best {MAX_MATCHES} are" for name, n in omitted.items()]
    out["warnings"] = [w.replace(tok, "***") for w in out["warnings"]]   # defence: no message carries the token
    return out
